#!/usr/bin/env bash
set -euo pipefail
source baseline-published/cuda-env.sh
export CUDA_VISIBLE_DEVICES=0
export PYTHONPATH="$PWD/baseline-published/python${PYTHONPATH:+:$PYTHONPATH}"
export PYTHONNOUSERSITE=1
export PYTHONUNBUFFERED=1
python3 - <<'EVALUATE'
import ctypes
import json
import math
import os
import pathlib
import re
import shutil
import subprocess
import time

mode = os.environ['EVAL_MODE']
if mode not in ('equivalence', 'warmup', 'performance', 'curve'):
    raise RuntimeError('Unsupported EVAL_MODE: '+mode)
root = pathlib.Path.cwd()
base = pathlib.Path(os.environ['BASELINE_DIR']).resolve()
out = pathlib.Path(os.environ['EVAL_OUT']).resolve()
out.mkdir(parents=True, exist_ok=True)
# A failed retry must not leave an earlier successful evaluation result in place.
if (out/'evaluation.json').exists():
    history = out/('evaluation.previous.'+str(time.time_ns())+'.json')
    (out/'evaluation.json').rename(history)
protocol = json.loads(pathlib.Path(os.environ['EVAL_PROTOCOL']).read_text())
inputs = json.loads(os.environ['EVAL_INPUTS'])
paired = json.loads(os.environ['EVAL_SEEDS'])
ids = inputs['ids']
if not isinstance(ids, list) or not ids or not all(isinstance(x,str) for x in ids):
    raise RuntimeError('EVAL_INPUTS.ids must contain sealed input identities')
if paired['kind'] == 'paired_median':
    seeds = paired['seeds']
    if not seeds or not all(type(seed) is int for seed in seeds):
        raise RuntimeError('Invalid execution seeds')
elif paired['kind'] == 'deterministic':
    seeds = [None]
else:
    raise RuntimeError('Unsupported seed protocol')
if 'timing_scope' in protocol:
    timing_scope = protocol['timing_scope']
else:
    sections = [protocol[key] for key in ('protocol','evaluation_protocol','evaluation')
                if isinstance(protocol.get(key),dict) and 'timing_scope' in protocol[key]]
    if len(sections) != 1:
        raise RuntimeError('Seal missing unambiguous timing_scope')
    timing_scope = sections[0]['timing_scope']
raw_budget = os.environ.get('EVAL_COMPUTE_BUDGET','')
budget = None
budget_s = None
if mode == 'curve':
    if not raw_budget:
        raise RuntimeError('Curve requires EVAL_COMPUTE_BUDGET in GPU seconds')
    budget = json.loads(raw_budget)
    if isinstance(budget, (int,float)) and not isinstance(budget,bool):
        budget_s = float(budget)
    elif isinstance(budget,dict):
        for key in ('gpu_seconds','gpu_s','budget_gpu_seconds','compute_budget_gpu_s','seconds'):
            if key in budget:
                budget_s = float(budget[key])
                break
    if budget_s is None or not math.isfinite(budget_s) or budget_s <= 0:
        raise RuntimeError('Invalid GPU-second curve budget')

# Child driver synchronizes through energy retrieval and Context destruction.
# Explicitly synchronize the sole visible device again before ending reported timers.
cuda = ctypes.CDLL('libcuda.so.1')
def checked(name, *args):
    status = getattr(cuda,name)(*args)
    if status != 0:
        raise RuntimeError(f'{name} failed: {status}')
checked('cuInit',ctypes.c_uint(0))
device = ctypes.c_int()
checked('cuDeviceGet',ctypes.byref(device),ctypes.c_int(0))
context = ctypes.c_void_p()
checked('cuDevicePrimaryCtxRetain',ctypes.byref(context),device)
def synchronize():
    checked('cuCtxSetCurrent',context)
    checked('cuCtxSynchronize')

def finite(value):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise RuntimeError('Missing or invalid measured number')
    return value

records = []
synchronize()
began = time.perf_counter()
try:
    for seed in seeds:
        for input_id in ids:
            # Sealed identities name this published fixed DHFR input; descriptive
            # keys in EVAL_INPUTS never create extra executions.
            record_dir = out/('record_'+str(len(records)))
            record_dir.mkdir(exist_ok=True)
            if (record_dir/'ensemble.json').exists() or (record_dir/'baseline.log').exists():
                archive = record_dir/('previous.'+str(time.time_ns()))
                archive.mkdir()
                for name in ('ensemble.json','baseline.log'):
                    if (record_dir/name).exists():
                        (record_dir/name).rename(archive/name)
            for name in ('5dfr_solv-cube_equil.pdb','amber99sb.xml','tip3p.xml'):
                shutil.copyfile(root/'data'/name,record_dir/name)
            seed0 = 1000 if seed is None else seed
            command = ['python3',os.path.relpath(base/'dhfr_ensemble.py',record_dir),
                       '--replicas','8','--steps','25000','--seed0',str(seed0)]
            remaining = 1170-(time.perf_counter()-began)
            if budget_s is not None:
                remaining = min(remaining,budget_s-(time.perf_counter()-began))
            if remaining <= 0:
                raise RuntimeError('Evaluation compute budget exhausted')
            with (record_dir/'baseline.log').open('wb') as log:
                subprocess.run(command,cwd=record_dir,stdout=log,stderr=subprocess.STDOUT,
                               check=True,timeout=remaining)
            synchronize()
            result = json.loads((record_dir/'ensemble.json').read_text())
            if result['platform'] != 'CUDA' or result['properties'] != {'Precision':'single','DeterministicForces':'true'}:
                raise RuntimeError('Measured platform/properties differ from published configuration')
            if result['simulated_ns'] != 0.8 or len(result['replicas']) != 8:
                raise RuntimeError('Measured scale differs from 8 x 25000 command')
            wall = finite(result['total_wall_s'])
            if wall <= 0:
                raise RuntimeError('Nonpositive reported completion time')
            metrics = {'total_wall_s':wall, 'simulated_ns':finite(result['simulated_ns']),
                       'aggregate_ns_per_day':result['simulated_ns']/wall*86400}
            for index,replica in enumerate(result['replicas']):
                if (replica['replica'],replica['seed'],replica['steps']) != (index,seed0+index,25000):
                    raise RuntimeError('Measured replica seeds/steps differ from execution command')
                for key in ('wall_s','mean_potential_kj_mol','final_potential_kj_mol'):
                    metrics[f'replica_{index}_{key}'] = finite(replica[key])
            text = (record_dir/'baseline.log').read_text()
            for name,places in (('total_wall_s',3),('aggregate_ns_per_day',1)):
                match = re.search(r'^'+name+r':\s*(\S+)\s*$',text,re.M)
                if not match or finite(float(match.group(1))) != float(f'{metrics[name]:.{places}f}'):
                    raise RuntimeError('Printed metric inconsistent with saved output: '+name)
            records.append({'input_id':input_id,'seed':seed,'metrics':metrics})
    synchronize()
    elapsed = time.perf_counter()-began
    if budget_s is not None and elapsed > budget_s:
        raise RuntimeError('GPU-second curve budget exceeded')
    evaluation = {'records':records,'timing_scope':timing_scope,'gpu_count':1,
                  'wall_s':elapsed,'compute_budget':budget}
    temporary = out/'evaluation.json.tmp'
    temporary.write_text(json.dumps(evaluation,allow_nan=False,indent=2)+'\n')
    temporary.replace(out/'evaluation.json')
finally:
    synchronize()
    checked('cuDevicePrimaryCtxRelease',device)
EVALUATE
